from typing import List

class Solution:
    def wordBreak(self, s: str, wordDict: List[str]) -> bool:
        def dfs(i: int) -> bool:
            if i == len(s):
                return True
            for word in wordDict:
                if s.startswith(word, i) and dfs(i + len(word)):
                    return True
            return False

        return dfs(0)

solutions.better:
from typing import List

class Solution:
    def wordBreak(self, s: str, wordDict: List[str]) -> bool:
        memo = {}

        def dfs(i: int) -> bool:
            if i == len(s):
                return True
            if i not in memo:
                memo[i] = any(
                    s.startswith(word, i) and dfs(i + len(word))
                    for word in wordDict
                )
            return memo[i]

        return dfs(0)

